<main class="login-shell"><div class="login-intro"><div class="brand"><span class="brand-icon"><?= icon('clock') ?></span>control<span class="brand-light">horario</span><span class="brand-dot"></span></div><div class="eyebrow">TU TIEMPO, EN ORDEN</div><h1>Cada jornada<br>cuenta.</h1><p>Registra tu asistencia y consulta tus horas.<br>Todo lo que necesitas, en un solo lugar.</p><div class="login-note"><?= icon('pin') ?><span>Marcado con ubicación y hora del servidor.</span></div></div><section class="panel login-card"><span class="eyebrow"><?= e(settings()['company']) ?></span><h2>Qué bueno verte</h2><p class="muted">Ingresa con tu RUT y contraseña.</p><?php flashes(); ?><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="login"><label>RUT<input name="rut" placeholder="12.345.678-5" autocomplete="username" maxlength="30" required></label><label>Contraseña<input type="password" name="password" autocomplete="current-password" maxlength="72" required></label><button class="button primary wide" type="submit">Iniciar sesión <?= icon('arrow') ?></button></form><p class="small muted">¿Olvidaste tu contraseña? Solicita el restablecimiento al administrador de tu institución.</p></section></main><?php footer(); echo '</body></html>'; }
function page_start(array $user,string $page): void {
    $titles=['locations'=>'Mis ubicaciones','dashboard'=>'Mi jornada','history'=>'Mi historial','overview'=>'Vista general','reports'=>'Reportes','profile'=>'Mi perfil','users'=>'Personas','user'=>'Gestión de persona','settings'=>'Configuración','audit'=>'Trazabilidad','edit'=>'Revisión de marcado','import'=>'Importar asistencia','absences'=>'Mis justificaciones','requests'=>'Solicitudes de inasistencia'];
    head($titles[$page]); ?>
<div class="app-layout"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-icon"><?= icon('clock') ?></span><span>control<span class="brand-light">horario</span></span></a><p class="sidebar-label">MI ESPACIO</p><nav aria-label="Principal"><?php
    $nav=$user['role']==='user'?['dashboard'=>['clock','Mi jornada'],'history'=>['file','Mi historial'],'profile'=>['user','Mi perfil'],'absences'=>['file','Mis justificaciones']]:[];
    if($user['role']!=='user') $nav+=['overview'=>['grid','Vista general'],'reports'=>['file','Reportes'],'requests'=>['file','Solicitudes'.(features_ready()?' ('.(int)query("SELECT COUNT(*) FROM ch_absences WHERE status='pending'")->fetchColumn().')':'')]];
    if($user['role']==='admin') $nav+=['users'=>['users','Personas'],'settings'=>['settings','Configuración'],'audit'=>['shield','Trazabilidad']];
    if($user['role']==='auditor') $nav+=['audit'=>['shield','Trazabilidad']];
    if($user['role']!=='user') $nav+=['profile'=>['user','Mi perfil']];
    foreach($nav as $key=>[$ico,$label]) echo '<a class="nav-link '.($page===$key?'active':'').'" href="index.php?page='.$key.'"'.($page===$key?' aria-current="page"':'').'>'.icon($ico).e($label).'</a>';
    ?></nav><div class="sidebar-bottom"><div class="connection"><span class="dot"></span><span data-connection>Conectado</span></div><p>Los marcados requieren conexión y ubicación.</p><button class="button secondary small-button" data-install hidden>Instalar aplicación</button><details class="install-help"><summary>Instalar en mi dispositivo</summary><p>Android o escritorio: usa «Instalar aplicación» en el navegador. En iPhone/iPad: Safari → Compartir → Agregar a inicio.</p></details></div></aside><div class="workspace"><header class="topbar"><span class="company"><?= e(settings()['company']) ?></span><div class="account"><span class="avatar"><?= e(strtoupper(substr($user['name'],0,1))) ?></span><span><strong><?= e($user['name']) ?></strong><small><?= e(role_label($user['role'])) ?></small></span><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="logout"><button class="text-button" title="Cerrar sesión">Salir</button></form></div></header><main class="main <?= $page==='dashboard'?'dashboard-main':'' ?>"><div class="page-heading"><div><div class="eyebrow">CONTROL DE ASISTENCIA</div><h1><?= e($titles[$page]) ?></h1></div><span class="date-chip"><?= e(date_label(today())) ?></span></div><?php flashes(); ?>
<div class="notice warning" data-offline hidden>Estás sin conexión. No se pueden registrar marcados. Reconecta y actualiza la página.</div>
<?php }
function page_end(): void { echo '</main>'; footer(); echo '</div></div></body></html>'; }
function stat_card(string $label,string $value,string $note,string $class=''): void { echo '<article class="stat '.e($class).'"><span>'.e($label).'</span><strong>'.e($value).'</strong><small>'.e($note).'</small></article>'; }
function status_badge(string $state): string {
    $class=match($state){'Completo','Justificada','Aprobada'=>'green','En jornada'=>'blue','Sin salida','Sin marcado','Anulado','Pendiente','Justificación pendiente'=>'orange',default=>'neutral'};
    return '<span class="badge '.$class.'">'.e($state).'</span>';
}
function dashboard_view(array $user): void {
    $date=today(); $a=row('SELECT * FROM ch_attendance WHERE user_id=? AND work_date=?',[$user['id'],$date]);
    $monday=(new DateTimeImmutable($date))->modify('monday this week')->format('Y-m-d'); $sunday=(new DateTimeImmutable($date))->modify('sunday this week')->format('Y-m-d');
    $data=report_data(['from'=>$monday,'to'=>$sunday,'user_id'=>(int)$user['id']]); $summary=$data['summaries'][0];
    $days=schedule_days((int)$user['id'],$date); $schedule=$days[(new DateTimeImmutable($date))->format('N')]??null; $holiday=row('SELECT name FROM ch_holidays WHERE date=?',[$date]);
    $todayAbsence=approved_absence((int)$user['id'],$date);
    $state=$todayAbsence?'Justificada':($a?($a['voided']?'Anulado':($a['clock_out']?'Completo':'En jornada')):'Sin ingreso');
    ?><p class="page-description">Tu jornada de hoy y el avance de tu semana, de un vistazo.</p>
<div class="dashboard-grid"><section class="panel punch-panel"><div class="panel-heading"><h2>Marca tu jornada</h2><?= status_badge($state) ?></div><div class="live-clock" data-clock data-server="<?= e((string)(time()*1000)) ?>" data-zone="<?= e(settings()['timezone']) ?>"><?= e(local_time(utc_now(),'H:i:s')) ?></div><p class="clock-caption">Hora local · <?= e(settings()['timezone']) ?></p><div class="punch-times"><div><span>Ingreso</span><strong><?= e($a?local_time($a['clock_in']):'—') ?></strong></div><div><span>Salida</span><strong><?= e($a?local_time($a['clock_out']):'—') ?></strong></div></div>
<?php if($todayAbsence): ?><div class="notice info">Inasistencia aprobada: <?= e(absence_categories()[$todayAbsence['category']]) ?>. Las horas programadas se contabilizan como justificadas. Si necesitas marcar, solicita primero al administrador la revisión de esta aprobación.</div><?php elseif(!$a || (!$a['voided'] && !$a['clock_out'])): ?><form method="post" class="stack" data-punch><?= csrf_field() ?><input type="hidden" name="action" value="punch"><input type="hidden" name="kind" value="<?= $a?'out':'in' ?>"><input type="hidden" name="challenge"><input type="hidden" name="latitude"><input type="hidden" name="longitude"><input type="hidden" name="accuracy"><?php if(!$a): ?><details class="punch-comment"><summary>Añadir comentario de ingreso (opcional)</summary><label>Comentario de ingreso <span class="optional">opcional</span><textarea name="comment" rows="2" maxlength="1000" placeholder="Puedes justificar un atraso o agregar una observación."></textarea></label></details><?php endif; ?><button class="button <?= $a?'secondary':'primary' ?> wide" type="submit"><?= icon($a?'arrow':'pin') ?> <?= $a?'Marcar salida':'Marcar ingreso' ?></button><p class="location-status small muted" role="status">La ubicación se solicita únicamente al marcar.</p><noscript><p>Activa JavaScript para obtener la ubicación y marcar.</p></noscript></form><?php else: ?><div class="notice <?= $a['voided']?'warning':'success' ?>"><?= $a['voided']?'Registro anulado. Contacta al administrador.':'Tu jornada de hoy está completada.' ?></div><?php endif; ?></section>
<section class="panel week-panel"><div class="panel-heading"><h2>Esta semana</h2><span class="small muted">Lun — Dom</span></div><div class="week-list"><?php foreach($data['details'] as $d): ?><div class="week-row <?= $d['date']===$date?'today':'' ?>"><div><strong><?= e(['1'=>'Lun','2'=>'Mar','3'=>'Mié','4'=>'Jue','5'=>'Vie','6'=>'Sáb','7'=>'Dom'][(new DateTimeImmutable($d['date']))->format('N')]) ?></strong><small><?= e(substr(date_label($d['date']),0,5)) ?></small></div><div class="week-middle"><span><?= e($d['holiday']?:$d['scheduled']) ?></span><small><?= e($d['status']) ?></small></div><strong><?= $d['credited']?e(hours($d['credited'])):'—' ?></strong></div><?php endforeach; ?></div><a class="inline-link" href="index.php?page=history">Ver mi historial <?= icon('arrow') ?></a></section></div>
<div class="stats"><?php stat_card('Horas computadas',hours($summary['credited']),hours($summary['minutes']).' trabajadas + '.hours($summary['justified']).' justificadas','accent'); stat_card('Meta de la semana',$summary['unscheduled']?'Sin definir':hours($summary['expected']),'Según horario y feriados'); stat_card('Por completar',$summary['unscheduled']?'—':hours(max(0,$summary['expected']-$summary['credited'])),'Considera horas trabajadas y justificadas'); stat_card('Registros abiertos',(string)$summary['pending'],'Incluye la jornada actual'); ?></div>
<?php user_locations_view($user,$date); ?>
<div class="info-strip"><?= icon('clock') ?><p><strong><?= $holiday?'Hoy es feriado: '.e($holiday['name']):($schedule?'Tu horario de hoy: '.e(implode(' a ',$schedule)):'Hoy no tienes un horario asignado') ?></strong><span>Colación incluida, sin marcado ni descuento. Las jornadas no pueden continuar al día siguiente.</span></p></div>
<?php $open=(int)query('SELECT COUNT(*) FROM ch_attendance WHERE user_id=? AND work_date<? AND clock_out IS NULL AND voided=0',[$user['id'],$date])->fetchColumn(); if($open): ?><div class="notice warning">Tienes <?= $open ?> jornada(s) anterior(es) sin salida. Solicita su corrección al analista; no se les asignarán horas automáticamente.</div><?php endif; }

function overview_view(): void {
    $date=today();
    $approved=features_ready()?array_column(rows("SELECT user_id,category FROM ch_absences WHERE work_date=? AND status='approved'",[$date]),'category','user_id'):[];
    $origin=features_ready()?'EXISTS(SELECT 1 FROM ch_import_items i WHERE i.attendance_id=a.id)':'0';
    $list=rows('SELECT u.id,u.name,u.rut,u.position,a.clock_in,a.clock_out,a.voided,a.comment,'.$origin.' AS imported FROM ch_users u LEFT JOIN ch_attendance a ON a.user_id=u.id AND a.work_date=? WHERE u.role=\'user\' AND u.active=1 AND u.start_date<=? ORDER BY u.name',[$date,$date]);
    $working=0;$done=0;$missing=0; foreach($list as $u) { if($u['clock_in'] && !$u['voided']) { if($u['clock_out']) $done++;else $working++; }else $missing++; }
    ?><p class="page-description">Estado de hoy de las personas activas con perfil Usuario.</p><div class="stats"><?php stat_card('Personas activas',(string)count($list),'Perfil Usuario, con fecha de inicio vigente');stat_card('En jornada',(string)$working,'Ingreso registrado','accent');stat_card('Jornada completa',(string)$done,'Ingreso y salida');stat_card('Sin ingreso',(string)$missing,'Incluye descansos y feriados'); ?></div><section class="panel"><div class="panel-heading"><h2>Asistencia de hoy</h2><a class="button secondary small-button" href="index.php?page=reports">Ver reportes</a></div><div class="table-wrap"><table><thead><tr><th>Persona</th><th>Ingreso</th><th>Salida</th><th>Estado</th><th>Comentario</th><th></th></tr></thead><tbody><?php foreach($list as $u): ?><tr><td><strong><?= e($u['name']) ?></strong><small><?= e(rut_label($u['rut'])) ?></small></td><td><?= e(local_time($u['clock_in'])) ?></td><td><?= e(local_time($u['clock_out'])) ?></td><td><?= status_badge($u['voided']?'Anulado':($u['clock_in']?($u['clock_out']?'Completo':'En jornada'):(isset($approved[$u['id']])?'Justificada':'Sin ingreso'))) ?></td><td class="comment-cell"><?= e(attendance_comment($u)?:'—') ?></td><td><a href="index.php?page=edit&amp;user_id=<?= (int)$u['id'] ?>&amp;date=<?= e($date) ?>">Revisar</a></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$list) echo '<p class="empty">No hay personas activas para hoy.</p>'; ?></section><?php }

function filter_form(array $f,string $page): void { ?>
<form method="get" class="filters panel"><input type="hidden" name="page" value="<?= e($page) ?>"><label>Desde<input type="date" name="from" value="<?= e($f['from']) ?>" required></label><label>Hasta<input type="date" name="to" value="<?= e($f['to']) ?>" required></label><?php if($page==='reports'): ?><label>Persona<select name="user_id"><option value="0">Todas las personas</option><?php foreach(rows('SELECT id,name,active FROM ch_users WHERE role=\'user\' ORDER BY name') as $u) echo '<option value="'.(int)$u['id'].'" '.((int)$u['id']===$f['user_id']?'selected':'').'>'.e($u['name']).(!$u['active']?' · Inactiva':'').'</option>'; ?></select></label><?php endif; ?><button class="button primary">Aplicar filtros</button><div class="quick-links"><a href="index.php?page=<?= e($page) ?>&amp;period=week">Esta semana</a><a href="index.php?page=<?= e($page) ?>&amp;period=month">Este mes</a></div></form>
<?php }
function reports_view(array $actor,string $page): void {
    $f=report_filters($actor); $data=report_data($f); filter_form($f,$page);
    $total=array_sum(array_column($data['summaries'],'minutes')); $justifiedTotal=array_sum(array_column($data['summaries'],'justified')); $pending=array_sum(array_column($data['summaries'],'pending'));
    ?><div class="report-heading"><p class="muted"><?= count($data['summaries']) ?> persona(s) · <strong><?= e(hours($total)) ?></strong> horas trabajadas · <strong><?= e(hours($justifiedTotal)) ?></strong> justificadas · <?= $pending ?> registro(s) abierto(s)</p><?php if($actor['role']!=='user' && $page==='reports'): ?><div class="actions"><a class="button secondary small-button" href="export.php?<?= e(http_build_query($f+['format'=>'xlsx'])) ?>">Descargar .xlsx</a><a class="button secondary small-button" href="export.php?<?= e(http_build_query($f+['format'=>'pdf'])) ?>">PDF</a></div><?php endif; ?></div>
<section class="panel"><div class="panel-heading"><h2>Cómputo semanal</h2><span class="small muted">Horas:minutos</span></div><p class="small muted">La meta descuenta feriados y usa el horario vigente de cada día. Las ausencias aprobadas cubren las horas programadas como justificadas. Computadas = trabajadas + justificadas; diferencia = computadas − meta. «Sin horario» no asigna una meta: referencia general <?= e(settings()['weekly_hours']) ?> h. Los rangos parciales sólo incluyen los días filtrados.</p><div class="table-wrap"><table><thead><tr><th>Persona</th><th>Semana desde</th><th>Trabajadas</th><th>Justificadas</th><th>Computadas</th><th>Meta</th><th>Diferencia</th><th>Abiertos</th></tr></thead><tbody><?php foreach($data['weeks'] as $w): ?><tr><td><?= e($w['name']) ?></td><td><?= e(date_label($w['week'])) ?><?= $w['partial']?'<small>Período parcial</small>':'' ?></td><td class="number"><?= e(hours($w['minutes'])) ?></td><td><?= e(hours($w['justified'])) ?></td><td><?= e(hours($w['credited'])) ?></td><td><?= $w['unscheduled']?'Sin horario':e(hours($w['expected'])) ?></td><td><?= $w['unscheduled']?'—':e(hours($w['credited']-$w['expected'])) ?></td><td><?= (int)$w['pending'] ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$data['weeks']) echo '<p class="empty">No hay datos para el período seleccionado.</p>'; ?></section>
<section class="panel"><div class="panel-heading"><h2>Detalle diario</h2><span class="small muted"><?= count($data['details']) ?> días</span></div><div class="table-wrap"><table><thead><tr><?php if($page==='reports') echo '<th>Persona</th>'; ?><th>Fecha</th><th>Ingreso</th><th>Salida</th><th>Trabajadas</th><th>Justificadas</th><th>Atraso</th><th>Estado</th><th>Observación</th><?php echo '<th></th>'; ?></tr></thead><tbody><?php
    $pg=max(1,(int)($_GET['p']??1)); $pages=max(1,(int)ceil(count($data['details'])/100)); $pg=min($pg,$pages);
    foreach(array_slice($data['details'],($pg-1)*100,100) as $d): $a=$d['record']; ?><tr><?php if($page==='reports') echo '<td>'.e($d['name']).'</td>'; ?><td><?= e(date_label($d['date'])) ?></td><td><?= e($a?local_time($a['clock_in']):'—') ?></td><td><?= e($a?local_time($a['clock_out']):'—') ?></td><td class="number"><?= $a && $a['clock_out'] && !$a['voided']?e(hours($d['minutes'])):'—' ?></td><td><?= e(hours($d['justified'])) ?></td><td><?= $d['late']?e(hours($d['late'])):'—' ?></td><td><?= status_badge($d['status']) ?></td><td class="comment-cell"><?= e(implode(' · ',array_filter([$d['holiday'],attendance_comment($a),isset($d['absence']['category'])?absence_categories()[$d['absence']['category']].' ('.absence_status($d['absence']['status']).')':'']))?:'—') ?></td><?php if($actor['role']!=='user' && $page==='reports'): ?><td><?php if($d['date']<=today()): ?><a href="index.php?page=edit&amp;user_id=<?= (int)$d['user_id'] ?>&amp;date=<?= e($d['date']) ?>">Revisar</a><?php endif; ?></td><?php elseif($page==='history'): ?><td><?php if($a): ?><a href="index.php?page=locations&amp;date=<?= e($d['date']) ?>">Ver ubicaciones</a><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><div class="pagination"><span>Página <?= $pg ?> de <?= $pages ?></span><?php if($pg>1): ?><a href="index.php?<?= e(http_build_query($f+['page'=>$page,'p'=>$pg-1])) ?>">Anterior</a><?php endif; if($pg<$pages): ?><a href="index.php?<?= e(http_build_query($f+['page'=>$page,'p'=>$pg+1])) ?>">Siguiente</a><?php endif; ?></div></section>
<p class="small muted">Las diferencias son informativas; no constituyen cálculo de remuneraciones. Un registro sin salida no suma horas hasta ser corregido.</p>
<?php }

