function edit_view(array $actor): void {
    $uid=(int)($_GET['user_id']??$_POST['user_id']??0); $date=is_string($_GET['date']??null)?$_GET['date']:today();
    if(!date_ok($date)) throw new DomainException('Fecha no válida.');
    $u=row('SELECT * FROM ch_users WHERE id=?',[$uid]); if(!$u) throw new DomainException('Persona no encontrada.');
    $a=row('SELECT * FROM ch_attendance WHERE user_id=? AND work_date=?',[$uid,$date]);
    if($actor['role']==='auditor') { auditor_review_view($actor,$u,$date,$a); return; }
    ?><a class="back-link" href="index.php?page=reports&amp;user_id=<?= $uid ?>">← Reportes de esta persona</a><div class="two-col"><section class="panel"><h2><?= e($u['name']) ?></h2><p class="muted"><?= e(rut_label($u['rut'])) ?> · <?= e(date_label($date)) ?></p><form method="get" class="inline-form"><input type="hidden" name="page" value="edit"><input type="hidden" name="user_id" value="<?= $uid ?>"><label>Fecha del registro<input type="date" name="date" value="<?= e($date) ?>" max="<?= e(today()) ?>" required></label><button class="button secondary">Consultar</button></form><hr><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="correct"><input type="hidden" name="user_id" value="<?= $uid ?>"><input type="hidden" name="work_date" value="<?= e($date) ?>"><input type="hidden" name="revision" value="<?= $a?(int)$a['revision']:0 ?>"><?php if(!$a): ?><div class="notice info">No existe marcado para este día. Si trabajó, completa las horas; si estuvo ausente, usa la justificación por jefatura.</div><?php endif; ?><div class="form-grid"><label><span class="time-label">Ingreso</span><input type="time" name="clock_in" value="<?= e($a?local_time($a['clock_in']):'') ?>" required></label><label><span class="time-label">Salida <span class="optional">opcional</span></span><input type="time" name="clock_out" value="<?= e($a && $a['clock_out']?local_time($a['clock_out']):'') ?>"></label></div><label>Motivo de la corrección<textarea name="reason" rows="3" maxlength="1000" required placeholder="Explica el permiso, atraso o la justificación de este ajuste."></textarea></label><?php if($actor['role']==='admin' && $a): ?><label class="check"><input type="checkbox" name="voided" <?= $a['voided']?'checked':'' ?>> Anular este registro (se conserva la trazabilidad)</label><?php endif; ?><button class="button primary">Guardar corrección</button><p class="small muted">Las horas corresponden a <?= e(settings()['timezone']) ?>. No se admiten jornadas de más de un día ni horas futuras.</p></form></section><section class="panel"><?php if(!$a || $a['voided']) management_absence_view($actor,$u,$date,$a); else locations_view($actor,$a); ?></section></div><section class="panel"><h2>Historial de cambios</h2><?php audit_table(review_audit_entries($a,$uid,$date)); ?></section><?php }

function users_view(): void { $search=is_string($_GET['q']??null)?substr(trim($_GET['q']),0,150):''; $users=rows('SELECT * FROM ch_users WHERE name LIKE ? OR rut LIKE ? ORDER BY active DESC,name',['%'.$search.'%','%'.normalize_rut($search).'%']); ?>
<div class="report-heading"><p class="page-description">Administra accesos, datos personales y horarios.</p><a class="button primary" href="index.php?page=user">+ Nueva persona</a></div><section class="panel"><form method="get" class="inline-form"><input type="hidden" name="page" value="users"><label>Buscar por nombre o RUT<input name="q" value="<?= e($search) ?>" placeholder="Nombre o RUT"></label><button class="button secondary">Buscar</button></form><div class="table-wrap"><table><thead><tr><th>Persona</th><th>Cargo / institución</th><th>Perfil</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['name']) ?></strong><small><?= e(rut_label($u['rut'])) ?></small></td><td><?= e($u['position']?:'—') ?><small><?= e($u['institution']) ?></small></td><td><?= e(role_label($u['role'])) ?></td><td><?= status_badge($u['active']?'Activa':'Inactiva') ?></td><td><a href="index.php?page=user&amp;user_id=<?= (int)$u['id'] ?>">Administrar</a></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$users) echo '<p class="empty">No se encontraron personas.</p>'; ?></section><?php }

function schedule_fields(array $days): void { ?>
<label>Tipo de horario<select name="schedule_mode" data-schedule-mode><option value="defined" <?= $days?'selected':'' ?>>Horario por día</option><option value="none" <?= !$days?'selected':'' ?>>Sin horario definido</option></select></label><div class="schedule-days"><div class="schedule-row schedule-label"><span>Día</span><span>Ingreso</span><span>Salida</span></div><?php foreach([1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo'] as $n=>$label): ?><div class="schedule-row"><span><?= e($label) ?></span><input type="time" name="start_<?= $n ?>" value="<?= e($days[$n][0]??'') ?>" aria-label="Ingreso <?= e($label) ?>"><input type="time" name="end_<?= $n ?>" value="<?= e($days[$n][1]??'') ?>" aria-label="Salida <?= e($label) ?>"></div><?php endforeach; ?></div><p class="small muted">Deja ambas horas vacías para un día de descanso. Colación incluida. Los feriados descuentan las horas de ese día.</p><?php }
function user_view(): void {
    $id=(int)($_GET['user_id']??0); $u=$id?row('SELECT * FROM ch_users WHERE id=?',[$id]):null;
    if($id && !$u) throw new DomainException('Persona no encontrada.');
    ?><a class="back-link" href="index.php?page=users">← Personas</a><div class="two-col"><section class="panel"><h2><?= $u?'Datos de la persona':'Crear una persona' ?></h2><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="user"><input type="hidden" name="user_id" value="<?= $id ?>"><div class="form-grid"><?php foreach(['name'=>['Nombre completo',150,true],'rut'=>['RUT',30,true],'email'=>['Correo electrónico',180,false],'phone'=>['Teléfono',40,false],'institution'=>['Empresa o institución',180,false],'position'=>['Cargo',150,false],'department'=>['Área',150,false],'address'=>['Dirección',250,false]] as $k=>[$label,$max,$required]): ?><label><?= e($label) ?><input type="<?= $k==='email'?'email':'text' ?>" name="<?= $k ?>" maxlength="<?= $max ?>" value="<?= e($u[$k]??($k==='institution'?settings()['company']:'')) ?>" <?= $required?'required':'' ?>></label><?php endforeach; ?><label>Perfil<select name="role"><?php foreach(['user','analyst','admin','auditor'] as $role) echo '<option value="'.$role.'" '.(($u['role']??'user')===$role?'selected':'').'>'.e(role_label($role)).'</option>'; ?></select></label><label>Fecha de inicio<input type="date" name="start_date" value="<?= e($u['start_date']??today()) ?>" required></label></div><label class="check"><input type="checkbox" name="active" <?= !$u || $u['active']?'checked':'' ?>> Cuenta activa</label><?php if(!$u): ?><label>Contraseña temporal<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><hr><h3>Horario inicial</h3><?php schedule_fields(default_days()); else: ?><label>Motivo del cambio<textarea name="reason" maxlength="1000" required></textarea></label><?php endif; ?><button class="button primary"><?= $u?'Guardar datos':'Crear persona' ?></button></form></section><div><?php if($u): ?><section class="panel"><div class="actions"><a class="button primary" href="index.php?page=import&amp;user_id=<?= $id ?>">Importar historial</a></div><hr><h2>Horario de trabajo</h2><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="schedule"><input type="hidden" name="user_id" value="<?= $id ?>"><label>Vigente desde<input type="date" name="effective_from" min="<?= e($u['start_date']) ?>" value="<?= e(max(today(),$u['start_date'])) ?>" required></label><?php schedule_fields(schedule_days($id,max(today(),$u['start_date']))); ?><label>Motivo<textarea name="reason" maxlength="1000" required></textarea></label><button class="button primary">Guardar horario</button></form><details><summary>Vigencias registradas</summary><?php foreach(rows('SELECT * FROM ch_schedules WHERE user_id=? ORDER BY effective_from DESC',[$id]) as $s): ?><div class="evidence"><strong>Desde <?= e(date_label($s['effective_from'])) ?></strong><pre><?= e(json_encode(json_decode($s['days_json']),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></div><?php endforeach; ?></details><p class="small muted">Una nueva vigencia conserva los períodos previos. Reemplazar una fecha existente o usar una fecha pasada recalcula ese período y queda auditado.</p></section><section class="panel"><h2>Restablecer contraseña</h2><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="reset"><input type="hidden" name="user_id" value="<?= $id ?>"><label>Nueva contraseña temporal<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><label>Motivo<textarea name="reason" maxlength="1000" required></textarea></label><button class="button secondary">Restablecer contraseña</button></form></section><?php else: ?><section class="panel"><h2>Un acceso, según su función</h2><dl class="profile-data"><div><dt>Usuario</dt><dd>Marca su jornada, consulta su historial y modifica sus datos de contacto.</dd></div><div><dt>Analista</dt><dd>Revisa toda la asistencia, exporta reportes y corrige marcados con justificación.</dd></div><div><dt>Administrador</dt><dd>Gestiona personas, horarios, feriados, empresa y trazabilidad.</dd></div><div><dt>Auditor</dt><dd>Consulta asistencia, solicitudes y trazabilidad; exporta reportes sin modificar ni aprobar registros.</dd></div></dl><p class="small muted">La contraseña temporal se entrega por el canal interno que utilice tu institución. El sistema no envía correos.</p></section><?php endif; ?></div></div><?php }

function settings_view(): void { $s=settings(); ?>
<p class="page-description">Una instalación para una empresa o institución.</p><div class="two-col"><section class="panel"><h2>Datos de la empresa</h2><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="settings"><label>Nombre<input name="company" value="<?= e($s['company']) ?>" maxlength="180" required></label><label>RUT de la empresa<input name="company_rut" value="<?= e($s['company_rut']) ?>" maxlength="20"></label><label>Dirección<input name="address" value="<?= e($s['address']) ?>" maxlength="250"></label><label>Referencia semanal general (horas)<input type="number" name="weekly_hours" value="<?= e($s['weekly_hours']) ?>" min="0.01" max="168" step="0.01" required></label><p class="small muted">La meta calculada usa el horario individual. Sin horario asignado, esta referencia se muestra sólo como orientación. Zona horaria fijada en la instalación: <?= e($s['timezone']) ?>.</p><label>Motivo del cambio<textarea name="reason" maxlength="1000" required></textarea></label><button class="button primary">Guardar configuración</button></form></section><section class="panel"><h2>Feriados</h2><p class="small muted">Descuentan las horas previstas del día. Si una persona marca en un feriado, sus horas efectivas se conservan.</p><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="holiday"><div class="form-grid"><label>Fecha<input type="date" name="date" required></label><label>Nombre<input name="name" maxlength="150" placeholder="Nombre del feriado" required></label></div><label>Motivo<input name="reason" maxlength="1000" required placeholder="Alta o actualización del calendario"></label><button class="button secondary">Agregar o actualizar feriado</button></form><hr><?php $holidays=rows('SELECT * FROM ch_holidays ORDER BY date DESC'); foreach($holidays as $h): ?><details class="holiday-item"><summary><?= e(date_label($h['date']).' · '.$h['name']) ?></summary><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="remove_holiday"><input type="hidden" name="date" value="<?= e($h['date']) ?>"><label>Motivo de eliminación<input name="reason" maxlength="1000" required></label><button class="button danger small-button">Eliminar feriado</button></form></details><?php endforeach; if(!$holidays) echo '<p class="empty">Todavía no has definido feriados.</p>'; ?></section></div><?php }

function audit_table(array $entries): void {
    if(!$entries) { echo '<p class="empty">No hay cambios registrados.</p>';return; }
    $actions=['punch_in'=>'Ingreso','punch_out'=>'Salida','coordinates'=>'Coordenadas','correct'=>'Corrección','void'=>'Anulación','create_user'=>'Creación de persona','update_user'=>'Edición de persona','schedule'=>'Horario','reset_password'=>'Restablecimiento de clave','profile'=>'Contacto','profile_password'=>'Contacto y contraseña','settings'=>'Configuración','holiday'=>'Feriado','remove_holiday'=>'Eliminación de feriado','install'=>'Instalación','import_insert'=>'Registro de asistencia','import_update'=>'Actualización de asistencia','import_batch'=>'Carga de historial','import_start_date'=>'Inicio histórico','absence_management'=>'Justificación por jefatura','absence_request'=>'Solicitud de inasistencia','absence_approved'=>'Justificación aprobada','absence_rejected'=>'Justificación rechazada','absence_cancelled'=>'Solicitud cancelada','absence_revoked'=>'Aprobación revocada','schema_update'=>'Actualización del sistema'];
    echo '<div class="audit-list">'; foreach($entries as $a): $a['before_json']=audit_display_json($a['before_json']); $a['after_json']=audit_display_json($a['after_json']); ?><details class="audit-item"><summary><span><strong><?= e($actions[$a['action']]??$a['action']) ?></strong><small><?= e(local_time($a['created_at'],'d/m/Y H:i:s').' · '.($a['actor']??'Sistema')) ?></small></span><span class="audit-reason"><?= e($a['reason']) ?></span></summary><p class="small muted">Referencia: <?= e($a['entity'].' #'.$a['entity_id']) ?> · Fechas internas en UTC.</p><?php context_view(security_ready()?row('SELECT * FROM ch_request_context WHERE audit_id=?',[$a['id']]):null); ?><div class="two-col"><div><h3>Antes</h3><pre><?= e($a['before_json']?json_encode(json_decode($a['before_json']),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE):'Sin valor anterior') ?></pre></div><div><h3>Después</h3><pre><?= e($a['after_json']?json_encode(json_decode($a['after_json']),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE):'Sin valor posterior') ?></pre></div></div></details><?php endforeach; echo '</div>'; }
function audit_view(): void { $pg=max(1,(int)($_GET['p']??1)); $count=(int)query('SELECT COUNT(*) FROM ch_audit')->fetchColumn(); $pages=max(1,(int)ceil($count/50)); $pg=min($pg,$pages); $offset=($pg-1)*50; ?>
<p class="page-description">Quién cambió qué, cuándo y por qué. Los registros de auditoría no se pueden editar desde el sistema.</p><section class="panel"><?php audit_table(rows('SELECT a.*,u.name actor FROM ch_audit a LEFT JOIN ch_users u ON u.id=a.actor_id ORDER BY a.id DESC LIMIT 50 OFFSET '.$offset)); ?><div class="pagination"><span>Página <?= $pg ?> de <?= $pages ?></span><?php if($pg>1) echo '<a href="index.php?page=audit&amp;p='.($pg-1).'">Anterior</a>'; if($pg<$pages) echo '<a href="index.php?page=audit&amp;p='.($pg+1).'">Siguiente</a>'; ?></div></section><?php }
